import Hatchet from '@hatchet-dev/typescript-sdk';
import fs from 'fs';

const hatchet = Hatchet.init();

const runId = process.env.ZEALT_RUN_ID || 'default';
const logFile = `/tmp/orders-${runId}.log`;

const processOrder = hatchet.task({
  name: 'processOrder',
  concurrency: {
    name: 'order-region-concurrency',
    key: 'input.region',
    maxRuns: 1,
  },
  fn: async (input: { region: string }) => {
    const { region } = input;

    // Append start log
    fs.appendFileSync(logFile, `start ${region} ${Date.now()}\n`);

    // Sleep 1.5 seconds
    await new Promise((resolve) => setTimeout(resolve, 1500));

    // Append end log
    fs.appendFileSync(logFile, `end ${region} ${Date.now()}\n`);

    return { status: 'completed', region };
  },
});

async function main() {
  const worker = await hatchet.worker('order-worker');
  await worker.register([processOrder]);
  console.log('Worker started and task registered');
  await worker.start();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import Hatchet from '@hatchet-dev/typescript-sdk';
import fs from 'fs';

const hatchet = Hatchet.init();

const runId = process.env.ZEALT_RUN_ID;
if (!runId) {
  console.error('ZEALT_RUN_ID environment variable is required');
  process.exit(1);
}

const logFile = `/tmp/orders-${runId}.log`;

async function main() {
  // Truncate log file
  fs.writeFileSync(logFile, '');
  console.log(`Truncated log file: ${logFile}`);

  const regions = [
    `US-${runId}`,
    `US-${runId}`,
    `EU-${runId}`,
    `EU-${runId}`,
  ];

  console.log(`Firing 4 runs for regions: ${regions.join(', ')}`);

  try {
    const runs = regions.map((region) =>
      hatchet.admin.run_workflow('processOrder', { region })
    );

    await Promise.all(runs);
    console.log('All runs completed');
  } catch (err) {
    console.error('Error running tasks:', err);
    process.exit(1);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

